// Quiet-comfort index — record JAH-GPCS-ANCHEADPHONES-000001
// Property of Justin Addam Higgins (JAH). Deterministic: same inputs, same output.
var m = {"anc_db": 30, "battery_h": 40, "price_usd": 350};
var value = (m.anc_db*m.battery_h/m.price_usd*10);
if (!isFinite(value)) { console.log('DEMO_FAIL|JAH-GPCS-ANCHEADPHONES-000001|non-finite'); process.exit(1); }
console.log('DEMO_OK|JAH-GPCS-ANCHEADPHONES-000001|' + value.toFixed(2) + ' quiet-comfort index');

